const required = ['customer_id','name','email','city','state'];
const file = $json;
return [{ json: { ...file, requiredFields: required, validationStatus: 'PENDING' } }];

const rows = items.map(i => i.json);
const required = ['customer_id','name','email','city','state'];
const seen = new Set();
const valid = [];
const invalid = [];
for (let index = 0; index < rows.length; index++) {
  const row = rows[index];
  const errors = [];
  for (const field of required) if (row[field] === undefined || row[field] === null || String(row[field]).trim() === '') errors.push(`${field}: required`);
  const key = row.customer_id ? String(row.customer_id).trim() : '';
  if (key && seen.has(key)) errors.push('customer_id: duplicate');
  if (key) seen.add(key);
  if (errors.length) invalid.push({ row_number: index + 2, ...row, validation_errors: errors });
  else valid.push(row);
}
return [{ json: { total_records: rows.length, valid_records: valid.length, invalid_records: invalid.length, duplicate_records: invalid.filter(r => r.validation_errors.includes('customer_id: duplicate')).length, valid, invalid } }];
